    "environment/tictactoe_env.py": "\"\"\"Finite-state Tic-Tac-Toe environment adhering to the Gymnasium API.\"\"\"\nfrom __future__ import annotations\nimport gymnasium as gym\nfrom typing import Tuple, List, Optional\nimport numpy as np\nimport random\nEMPTY_ACTION: int = -1\nWINNING_LINES: List[Tuple[int, ...]] = [(0, 1, 2), (3, 4, 5), (6, 7, 8), (0, 3, 6), (1, 4, 7), (2, 5, 8), (0, 4, 8), (2, 4, 6)]\nBOARD_SIZE: int = 9\nMAX_PLAYERS: List[int] = [1, -1]\n\nclass TicTacToeEnv(gym.Env):\n    \"\"\"\n    A tabular Tic-Tac-Toe environment using the Gymnasium interface.\n\n    The board is flattened to a 1D array of length 9 (indices 0-8).\n    Player X (value +1) always moves first. Player O (value -1) moves second.\n    Rewards are: +1 for winning, 0 for draw, -1 for losing.\n    Truncation is triggered if the game exceeds a reasonable move limit \n    to prevent infinite loops in edge cases, though Tic-Tac-Toe guarantees termination by state space logic.\n    \"\"\"\n    render_mode: 'object'\n    observation_space: 'object'\n    action_space: 'object'\n    metadata = {'render_modes': ['ansi']}\n\n    def __init__(self, render_mode: Optional[str]=None) -> None:\n        \"\"\"\n        Initialize the environment.\n\n        Args:\n            render_mode: Optional rendering mode. Not implemented in this stub context,\n                         but kept for Gymnasium compatibility.\n        \"\"\"\n        ...\n    def reset(self, seed: Optional[int]=None, options: Optional[dict]=None) -> Tuple[np.ndarray, dict]:\n        \"\"\"\n        Reset the environment to the initial state.\n\n        Args:\n            seed: Optional random seed for reproducibility.\n            options: Additional options (unused).\n\n        Returns:\n            observation: The initial board state as a numpy array.\n            info: A dictionary containing auxiliary information (empty in this context).\n        \"\"\"\n        ...\n    def step(self, action: int) -> Tuple[np.ndarray, float, bool, bool, dict]:\n        \"\"\"\n        Execute one time step in the environment.\n\n        Args:\n            action: An integer in [0, 8] representing the grid index to place a mark.\n\n        Returns:\n            observation: The new board state.\n            reward: +1 if the current player wins, -1 if they lose, 0 otherwise.\n            terminated: True if the game is over (win/loss/draw).\n            truncated: Always False in standard Tic-Tac-Toe unless hard limits are added.\n            info: Auxiliary info containing valid actions for the next turn.\n\n        Raises:\n            ValueError: If the action is invalid (occupied or out of bounds).\n        \"\"\"\n        ...\n    def get_valid_actions(self) -> List[int]:\n        \"\"\"\n        Return a list of valid (empty) actions available in the current state.\n\n        Returns:\n            A list of integers representing indices of empty cells on the board.\n        \"\"\"\n        ...\n    def _check_win(self, player: int) -> bool:\n        \"\"\"\n        Check if a specific player has won. Uses precomputed winning lines.\n\n        Args:\n            player: The player ID (+1 or -1) to check for.\n\n        Returns:\n            True if the player has formed a line, False otherwise.\n        \"\"\"\n        ...\n    def _get_winner(self) -> int:\n        \"\"\"\n        Determine the winner of the current board state.\n\n        Returns:\n            +1 if Player X wins, -1 if Player O wins, 0 if draw or no winner yet.\n        \"\"\"\n        ...",
    "agents/q_agent.py": "\"\"\"Tabular Q-Learning agent implementation for Tic-Tac-Toe.\"\"\"\nfrom __future__ import annotations\nimport copy\nfrom typing import Any, Dict, Optional, Tuple\nfrom environment.tictactoe_env import BOARD_SIZE\nDEFAULT_LEARNING_RATE: float = 0.1\nDEFAULT_DISCOUNT_FACTOR: float = 0.95\nDEFAULT_EPSILON: float = 0.1\n\nclass QLearningAgent:\n    \"\"\"\n    Implements a Tabular Q-Learning agent with epsilon-greedy exploration.\n\n    The Q-table is stored as a dictionary mapping string-encoded board states\n    to arrays of action values (one per possible move index 0-8).\n    \"\"\"\n    lr: 'float'\n    gamma: 'float'\n    epsilon: 'float'\n\n    def __init__(self, lr: float=DEFAULT_LEARNING_RATE, gamma: float=DEFAULT_DISCOUNT_FACTOR, epsilon: float=DEFAULT_EPSILON) -> None:\n        \"\"\"\n        Initialize the Q-Learning agent.\n\n        Args:\n            lr: The learning rate (alpha) for the Bellman update. Should be in (0, 1].\n            gamma: The discount factor for future rewards. Should be in [0, 1).\n            epsilon: The probability of choosing a random action during exploration.\n                     In [0, 1]. Higher values lead to more exploration.\n        \"\"\"\n        ...\n    def act(self, state: Any) -> int:\n        \"\"\"\n        Select an action based on the current state using epsilon-greedy policy.\n\n        Args:\n            state: The current environment observation (typically a numpy array or tuple).\n                   It must be hashable/convertible to a string key for the Q-table.\n\n        Returns:\n            An integer in [0, 8] representing the chosen move index.\n\n        Behavior:\n            - With probability epsilon, returns a random action in [0, 8].\n            - Otherwise, returns the action with the highest Q-value for this state.\n              If there are ties, the first one encountered is selected.\n            - If the state has never been seen, treats all Q-values as 0.\