    "agents/q_agent.py": "\"\"\"Tabular Q-Learning agent implementation for Tic-Tac-Toe.\"\"\"\nfrom __future__ import annotations\nimport copy\nimport random\nfrom typing import Dict, List, Optional, Tuple\nimport numpy as np\nDEFAULT_LEARNING_RATE: float = 0.1\nDEFAULT_DISCOUNT_FACTOR: float = 0.95\nDEFAULT_EPSILON: float = 0.1\n\nclass QLearningAgent:\n    \"\"\"\n    Implements a Tabular Q-Learning agent with epsilon-greedy exploration.\n\n    The Q-table maps hashable state representations (tuples of integers) to lists\n    of action values (one per possible move index 0-8).\n    \"\"\"\n    lr: 'float'\n    gamma: 'float'\n    epsilon: 'float'\n\n    def __init__(self, lr: float=DEFAULT_LEARNING_RATE, gamma: float=DEFAULT_DISCOUNT_FACTOR, epsilon: float=DEFAULT_EPSILON) -> None:\n        \"\"\"\n        Initialize the Q-Learning agent.\n\n        Args:\n            lr: The learning rate (alpha) for the Bellman update. Should be in (0, 1].\n            gamma: The discount factor for future rewards. Should be in [0, 1).\n            epsilon: The probability of choosing a random action during exploration.\n                     In [0, 1]. Higher values lead to more exploration.\n        \"\"\"\n        ...\n    def act(self, state: np.ndarray, valid_actions: List[int]) -> int:\n        \"\"\"\n        Select an action based on the current state using epsilon-greedy policy.\n\n        Args:\n            state: The current environment observation as a numpy array (length 9, dtype float32/int). \n                   It is converted to a tuple internally for dictionary keying.\n            valid_actions: A list of integer action indices that are legal in the current state.\n                           The selected action will always be drawn from this list.\n\n        Returns:\n            An integer from `valid_actions` representing the chosen move index.\n\n        Raises:\n            ValueError: If `valid_actions` is empty.\n\n        Behavior:\n            - With probability epsilon, returns a uniformly random action from `valid_actions`.\n            - Otherwise, returns an action from `valid_actions` that maximizes the Q-value for `state`.\n              If multiple actions have the same maximal Q-value, one is chosen arbitrarily (deterministic order).\n            - If the state has never been seen, treats all unseen actions' Q-values as 0.\n        \"\"\"\n        ...\n    def learn(self, state: np.ndarray, action: int, reward: float, next_state: np.ndarray, done: bool, valid_actions_next: List[int]) -> None:\n        \"\"\"\n        Perform a Q-Learning update step (Bellman equation).\n\n        Updates the Q-value for (state, action) using the target:\n        R + gamma * max_{a' in valid_actions_next} Q(next_s, a') if not done, else R.\n\n        Args:\n            state: The state before the action as a numpy array. Must be convertible to tuple for keying.\n            action: The integer action taken in 'state'.\n            reward: The immediate reward received after taking 'action'.\n            next_state: The resulting state after 'action' as a numpy array. Must be convertible to tuple for keying.\n            done: Boolean indicating if the episode has terminated. If True, no future\n                  reward is considered.\n            valid_actions_next: A list of integer action indices that are legal in `next_state`.\n                                Used to compute the maximum Q-value for the next state.\n        \"\"\"\n        ...\n    def q_table(self) -> Dict[Tuple[int, ...], List[float]]:\n        \"\"\"\n        Return a copy of the internal Q-table.\n\n        Returns:\n            A dictionary mapping state representations (tuples of ints) to lists of Q-values (floats).\n            The returned object is a deep copy; modifying it does not affect the agent's\n            internal state.\n        \"\"\"\n        ...",
    "agents/random_agent.py": "\"\"\"Baseline random agent for Tic-Tac-Toe.\"\"\"\nfrom __future__ import annotations\nimport numpy as np\nimport random\nfrom typing import List\n\nclass RandomAgent:\n    \"\"\"\n    A baseline agent that selects uniformly at random from valid actions.\n\n    This agent serves as a performance floor. It does not learn; it chooses\n    any legal move with equal probability.\n    \"\"\"\n    name: str = 'random_agent'\n\n    def act(self, state: np.ndarray, valid_actions: List[int]) -> int:\n        \"\"\"\n        Select a random action from the provided list of valid actions.\n\n        Args:\n            state: The current observation (board state). Unused for logic,\n                   kept for interface consistency with QLearningAgent.\n            valid_actions: A list of integers representing legal move indices.\n\n        Returns:\n            An integer representing the selected action index, drawn uniformly\n            from `valid_actions`.\n\n        Edge cases:\n            - If `valid_actions` is empty (e.g., game already over), raises\n              IndexError. Callers should check termination status before calling.\n        \"\"\"\n        ...",
    "experiment/run_experiment.py": "\"\"\"Orchestrates training of the Q-learning agent against a random opponent and evaluates it against the random baseline, saving metrics to results.csv.\"\"\"\nfrom __future__ import annotations\nimport os\nfrom typing import List\nimport numpy as np\nimport pandas as pd\nfrom agents.q_agent import QLearningAgent\nfrom agents.random_agent import RandomAgent\nfrom environment.tictactoe_env import TicTacToeEnv\nN_EPISODES: int = 50000\nN_EVALUATION_GAMES: int = 2000\nLEARNING_RATE: float = 0.1\nDISCOUNT_FACTOR: float = 0.95\nEXPLORATION_EPSILON_TRAINING: float = 0.1\nEXPLORATION_EPSILON_INFERENCE: float = 0.0\nSEED: int = 42\nRESULTS_FILENAME: str = 'results.csv'\n\ndef _play_game(env: TicTacToeEnv, agent_x: QLearningAgent | RandomAgent, agent_o: QLearningAgent | RandomAgent, epsilon: float) -> int:\n    \"\"\"\n    Simulate a single game of Tic-Tac-Toe between two agents.\n\n    The environment starts with Player X moving first. The function tracks the\n    outcome from the perspective of the agent playing as Player X (`agent_x`).\n\n    Args:\n        env: A reset TicTacToeEnv instance ready for a new game.\n        agent_x: The agent controlling Player X (+1).\n        agent_o: The agent controlling Player O (-1).\n        epsilon: Exploration rate used by `agent_x` if it is a QLearningAgent.\n                 Ignored if `agent_x` is a RandomAgent.\n\n    Returns:\n        An integer result code from the perspective of Player X (`agent_x`):\n        1 if Player X wins,\n        0 if the game ends in a draw,\n        -1 if Player O wins.\n    \"\"\"\n    ...\ndef _compute_metrics(results: List[int]) -> tuple[float, float, float]:\n    \"\"\"\n    Calculate win, draw, and loss rates from a list of game results.\n\n    Args:\n        results: A list of integers (1 for win, 0 for draw, -1 for loss)\n                 from the perspective of the primary agent.\n\n    Returns:\n        A tuple (win_rate, draw_rate, loss_rate), where each rate is a float in [0, 1].\n        The sum of the three rates will be approximately 1.0.\n    \"\"\"\n    ...\ndef run_study() -> None:\n    \"\"\"\n    Execute the full training and evaluation pipeline for the Q-Learning agent.\n\n    This function:\n    1. Initializes the TicTacToe environment, the Q-learning agent, and the Random baseline agent.\n    2. Trains the Q-agent against a random opponent for `N_EPISODES` episodes.\n       It tracks the training reward to monitor convergence.\n    3. Evaluates the trained Q-agent against the Random Agent in `N_EVALUATION_GAMES` games,\n       averaging results over both playing positions (X and O).\n    4. Evaluates the Random Agent against itself in `N_EVALUATION_GAMES` games to establish a baseline.\n    5. Aggregates the results into a pandas DataFrame with columns `method`, `metric`, `value`,\n       and saves it to `results.csv` in the current working directory.\n\n    Metrics saved:\n        - Method 'q_learning':\n            - win_rate: Win rate against Random Agent (averaged over X and O positions).\n            - draw_rate: Draw rate against Random Agent.\n            - loss_rate: Loss rate against Random Agent.\n        - Method 'random_agent':\n            - win_rate: Win rate against another Random Agent.\n            - draw_rate: Draw rate against another Random Agent.\n            - loss_rate: Loss rate against another Random Agent.\n    \"\"\"\n    ...",
